class CusUtil(RtgUtil):
    """Command for cus_util script."""

    def __init__(self, connection, usage, path="/opt/cus/bin/cus-util.py", options=None, prompt=None,
                 newline_chars=None, runner=None):
        """
        Cus util command.

        :param connection: moler connection to device, terminal when command is executed.
        :param usage: Usage of script. mac|link|rsi|ver|fix|ufix|ovhd|mmi|sshc|rmod|rup|recover|fd1|fd2|getp|check
        :param path: Path to cus-util script.
        :param options: parameter with which the command will be executed
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(CusUtil, self).__init__(connection, usage, path=path, options=options, prompt=prompt,
                                      newline_chars=newline_chars, runner=runner)


